This is an AVX2 kernel. It does an in-register inclusive scan on 4-element vectors, which keeps the serial dependency to one add per vector through a broadcast carry. Output uses non-temporal stores, after a scalar head aligns `out` to 32 bytes, to avoid read-for-ownership traffic. I have not compiled or run it.

<answer>
```c
#include <immintrin.h>

void prefix_sum_i64(const int64_t *in, int64_t *out, size_t n) {
    size_t i = 0;
    int64_t carry = 0;

    /* scalar head: align out to 32 bytes */
    while (i < n && ((uintptr_t)(out + i) & 31)) {
        carry += in[i];
        out[i] = carry;
        i++;
    }

    __m256i c = _mm256_set1_epi64x(carry);

    for (; i + 4 <= n; i += 4) {
        __m256i x = _mm256_loadu_si256((const __m256i *)(in + i));
        /* in-lane shift by one element: [0,a,0,c] */
        x = _mm256_add_epi64(x, _mm256_slli_si256(x, 8));
        /* x = [a, a+b, c, c+d] ; broadcast a+b to high lanes */
        __m256i p = _mm256_permute4x64_epi64(x, 0x55);
        p = _mm256_blend_epi32(_mm256_setzero_si256(), p, 0xF0);
        x = _mm256_add_epi64(x, p);   /* local inclusive scan */
        /* broadcast total of this vector */
        __m256i tot = _mm256_permute4x64_epi64(x, 0xFF);
        __m256i res = _mm256_add_epi64(x, c);
        _mm256_stream_si256((__m256i *)(out + i), res);
        c = _mm256_add_epi64(c, tot);  /* short carry chain */
    }

    carry = _mm256_extract_epi64(c, 0);
    _mm_sfence();

    for (; i < n; i++) {
        carry += in[i];
        out[i] = carry;
    }
}
```
</answer>

This is an AVX2 in-register scan. Each 4-element vector gets a local inclusive scan, then a running carry vector is added. The carry chain is one add per vector. Output is written with non-temporal stores when the array is large, since the output is write-only traffic. I haven't compiled or run it.

<answer>
```c
#include <immintrin.h>
#include <stdint.h>
#include <stddef.h>

void prefix_sum_i64(const int64_t *in, int64_t *out, size_t n) {
    size_t i = 0;
    int64_t carry = 0;

    /* scalar head until out+i is 32-byte aligned */
    while (i < n && ((uintptr_t)(out + i) & 31)) {
        carry += in[i];
        out[i] = carry;
        i++;
    }

    __m256i cv = _mm256_set1_epi64x(carry);
    const __m256i zero = _mm256_setzero_si256();

    if (n - i >= ((size_t)1 << 20)) {
        for (; i + 4 <= n; i += 4) {
            __m256i v = _mm256_loadu_si256((const __m256i *)(in + i));
            v = _mm256_add_epi64(v, _mm256_slli_si256(v, 8));
            __m256i t = _mm256_permute4x64_epi64(v, 0x55);
            v = _mm256_add_epi64(v, _mm256_blend_epi32(zero, t, 0xF0));
            __m256i o = _mm256_add_epi64(v, cv);
            _mm256_stream_si256((__m256i *)(out + i), o);
            cv = _mm256_add_epi64(cv, _mm256_permute4x64_epi64(v, 0xFF));
        }
        _mm_sfence();
    } else {
        for (; i + 4 <= n; i += 4) {
            __m256i v = _mm256_loadu_si256((const __m256i *)(in + i));
            v = _mm256_add_epi64(v, _mm256_slli_si256(v, 8));
            __m256i t = _mm256_permute4x64_epi64(v, 0x55);
            v = _mm256_add_epi64(v, _mm256_blend_epi32(zero, t, 0xF0));
            __m256i o = _mm256_add_epi64(v, cv);
            _mm256_storeu_si256((__m256i *)(out + i), o);
            cv = _mm256_add_epi64(cv, _mm256_permute4x64_epi64(v, 0xFF));
        }
    }

    carry = _mm256_cvtsi256_si64(cv);

    for (; i < n; i++) {
        carry += in[i];
        out[i] = carry;
    }
}
```
</answer>

This is an AVX2 version. It peels scalar elements until the output is 32-byte aligned, then processes four int64 values per iteration. Each vector is scanned in-register with two permute-and-blend steps, and a broadcast carry is added. The carry chain is one vector add per iteration, and the output uses non-temporal stores to avoid read-for-ownership traffic on the 128 MB output. I haven't compiled or run it.

<answer>
```c
#include <immintrin.h>
#include <stdint.h>
#include <stddef.h>

void prefix_sum_i64(const int64_t *in, int64_t *out, size_t n) {
    size_t i = 0;
    int64_t run = 0;
    while (i < n && ((uintptr_t)(out + i) & 31)) {
        run += in[i];
        out[i] = run;
        i++;
    }
    if (n - i >= 4) {
        __m256i C = _mm256_set1_epi64x(run);
        const __m256i zero = _mm256_setzero_si256();
        for (; i + 4 <= n; i += 4) {
            __m256i v = _mm256_loadu_si256((const __m256i *)(in + i));
            __m256i t = _mm256_blend_epi32(_mm256_permute4x64_epi64(v, 0x90), zero, 0x03);
            __m256i s = _mm256_add_epi64(v, t);
            t = _mm256_blend_epi32(_mm256_permute4x64_epi64(s, 0x40), zero, 0x0F);
            s = _mm256_add_epi64(s, t);
            __m256i o = _mm256_add_epi64(s, C);
            _mm256_stream_si256((__m256i *)(out + i), o);
            C = _mm256_add_epi64(C, _mm256_permute4x64_epi64(s, 0xFF));
        }
        _mm_sfence();
        run = _mm256_extract_epi64(C, 0);
    }
    for (; i < n; i++) {
        run += in[i];
        out[i] = run;
    }
}
```
