This uses eight sub-histograms so that consecutive increments of the same byte, which a run produces, go to different tables. That keeps the increments off a single dependency chain. The tables are 16 KiB on the stack, well under the 4 MiB limit, and the tail and empty inputs fall through the scalar loop.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>

void byte_histogram(const uint8_t *data, size_t n, uint64_t counts[256]) {
    uint64_t h[8][256];
    memset(h, 0, sizeof(h));
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        h[0][data[i + 0]]++;
        h[1][data[i + 1]]++;
        h[2][data[i + 2]]++;
        h[3][data[i + 3]]++;
        h[4][data[i + 4]]++;
        h[5][data[i + 5]]++;
        h[6][data[i + 6]]++;
        h[7][data[i + 7]]++;
    }
    for (; i < n; i++) {
        h[0][data[i]]++;
    }
    for (int b = 0; b < 256; b++) {
        counts[b] = h[0][b] + h[1][b] + h[2][b] + h[3][b]
                  + h[4][b] + h[5][b] + h[6][b] + h[7][b];
    }
}
```
