This is a segmented, odd-only sieve of Eratosthenes. It keeps a 64 KiB byte buffer that stays in L2 cache, plus a small table of base primes up to sqrt(n), so the extra memory is well under the 4 MiB limit. I haven't compiled or run it, but I traced the edge cases (n < 3, n = 3) by hand.

<answer>
```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define K_SEG_BYTES (1u << 16)

static uint8_t k_seg[K_SEG_BYTES];

uint64_t count_primes(uint64_t n) {
    if (n < 2) return 0;
    uint64_t total = 1; /* prime 2 */
    if (n < 3) return total;

    /* integer sqrt */
    uint64_t r = (uint64_t)__builtin_sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    /* base odd primes up to r */
    uint8_t *cmp = (uint8_t *)calloc(r + 2, 1);
    uint64_t *pr = (uint64_t *)malloc(sizeof(uint64_t) * (r / 2 + 4));
    size_t np = 0;
    if (!cmp || !pr) {
        free(cmp);
        free(pr);
        return 0;
    }
    for (uint64_t i = 3; i <= r; i += 2) {
        if (!cmp[i]) {
            pr[np++] = i;
            for (uint64_t j = i * i; j <= r; j += 2 * i) cmp[j] = 1;
        }
    }
    free(cmp);

    const uint64_t SEG = K_SEG_BYTES;
    uint64_t low = 3;
    while (low <= n) {
        uint64_t last = low + 2 * (SEG - 1);
        if (last > n) last = n;
        uint64_t cnt = (last - low) / 2 + 1;
        memset(k_seg, 1, (size_t)cnt);

        for (size_t k = 0; k < np; k++) {
            uint64_t p = pr[k];
            uint64_t pp = p * p;
            if (pp > last) break;
            uint64_t s;
            if (pp >= low) {
                s = pp;
            } else {
                s = ((low + p - 1) / p) * p;
                if (!(s & 1)) s += p;
            }
            uint64_t j = (s - low) / 2;
            for (; j < cnt; j += p) k_seg[j] = 0;
        }

        uint64_t c = 0;
        for (uint64_t j = 0; j < cnt; j++) c += k_seg[j];
        total += c;

        low += 2 * SEG;
    }

    free(pr);
    return total;
}
```
</answer>

This uses the Lucy_Hedgehog method, which computes π(n) in roughly O(n^{3/4}) time. For n ≈ 5·10^7 that is a few million operations, far fewer than a sieve. Memory is two arrays of about √n entries (under 120 KB), well inside the 4 MiB limit. It is single-threaded, keeps no state across calls, and handles n < 2 explicitly. I have not compiled or run it.

<answer>
```c
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

uint64_t count_primes(uint64_t n) {
    if (n < 2) return 0;
    uint64_t r = (uint64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    uint64_t *small = (uint64_t *)malloc((size_t)(r + 2) * sizeof(uint64_t));
    uint64_t *large = (uint64_t *)malloc((size_t)(r + 2) * sizeof(uint64_t));
    if (!small || !large) {
        free(small);
        free(large);
        return 0;
    }

    small[0] = 0;
    for (uint64_t v = 1; v <= r; v++) small[v] = v - 1;
    for (uint64_t i = 1; i <= r; i++) large[i] = n / i - 1;

    for (uint64_t p = 2; p <= r; p++) {
        if (small[p] == small[p - 1]) continue;
        uint64_t sp = small[p - 1];
        uint64_t p2 = p * p;
        uint64_t lim = n / p2;
        if (lim > r) lim = r;
        for (uint64_t i = 1; i <= lim; i++) {
            uint64_t d = i * p;
            uint64_t t;
            if (d <= r) t = large[d];
            else t = small[n / d];
            large[i] -= t - sp;
        }
        if (p2 <= r) {
            for (uint64_t v = r; v >= p2; v--) {
                small[v] -= small[v / p] - sp;
                if (v == p2) break;
            }
        }
    }

    uint64_t result = large[1];
    free(small);
    free(large);
    return result;
}
```
</answer>

This is an AVX2/FMA register-blocked kernel: it computes 4×16 tiles of C, streaming down a 16-column panel of B. Rows and columns that don't fill a full tile go through a scalar path. Accumulation stays in float with FMA in k order, so the error stays well inside the 1e-4 tolerance. I haven't compiled or run it.

<answer>
```c
#include <stddef.h>
#include <immintrin.h>

void matmul_f32(const float *A, const float *B, float *C, size_t n) {
    if (n == 0) return;
#if defined(__AVX2__) && defined(__FMA__)
    size_t jn = n & ~(size_t)15;
    size_t in = n & ~(size_t)3;
    for (size_t j0 = 0; j0 < jn; j0 += 16) {
        for (size_t i0 = 0; i0 < in; i0 += 4) {
            __m256 c00 = _mm256_setzero_ps(), c01 = _mm256_setzero_ps();
            __m256 c10 = _mm256_setzero_ps(), c11 = _mm256_setzero_ps();
            __m256 c20 = _mm256_setzero_ps(), c21 = _mm256_setzero_ps();
            __m256 c30 = _mm256_setzero_ps(), c31 = _mm256_setzero_ps();
            const float *a0 = A + (i0 + 0) * n;
            const float *a1 = A + (i0 + 1) * n;
            const float *a2 = A + (i0 + 2) * n;
            const float *a3 = A + (i0 + 3) * n;
            const float *bp = B + j0;
            for (size_t k = 0; k < n; k++) {
                __m256 b0 = _mm256_loadu_ps(bp + k * n);
                __m256 b1 = _mm256_loadu_ps(bp + k * n + 8);
                __m256 av;
                av = _mm256_broadcast_ss(a0 + k);
                c00 = _mm256_fmadd_ps(av, b0, c00);
                c01 = _mm256_fmadd_ps(av, b1, c01);
                av = _mm256_broadcast_ss(a1 + k);
                c10 = _mm256_fmadd_ps(av, b0, c10);
                c11 = _mm256_fmadd_ps(av, b1, c11);
                av = _mm256_broadcast_ss(a2 + k);
                c20 = _mm256_fmadd_ps(av, b0, c20);
                c21 = _mm256_fmadd_ps(av, b1, c21);
                av = _mm256_broadcast_ss(a3 + k);
                c30 = _mm256_fmadd_ps(av, b0, c30);
                c31 = _mm256_fmadd_ps(av, b1, c31);
