            _mm256_storeu_ps(cp + 8, c01);
            cp += n;
            _mm256_storeu_ps(cp, c10);
            _mm256_storeu_ps(cp + 8, c11);
            cp += n;
            _mm256_storeu_ps(cp, c20);
            _mm256_storeu_ps(cp + 8, c21);
            cp += n;
            _mm256_storeu_ps(cp, c30);
            _mm256_storeu_ps(cp + 8, c31);
        }
    }
    /* remaining columns for rows < in */
    for (size_t i = 0; i < in; i++) {
        for (size_t j = jn; j < n; j++) {
            float s = 0.0f;
            for (size_t k = 0; k < n; k++) s += A[i * n + k] * B[k * n + j];
            C[i * n + j] = s;
        }
    }
    /* remaining rows, all columns */
    for (size_t i = in; i < n; i++) {
        for (size_t j = 0; j < n; j++) {
            float s = 0.0f;
            for (size_t k = 0; k < n; k++) s += A[i * n + k] * B[k * n + j];
            C[i * n + j] = s;
        }
    }
#else
    for (size_t i = 0; i < n; i++) {
        float *ci = C + i * n;
        for (size_t j = 0; j < n; j++) ci[j] = 0.0f;
        for (size_t k = 0; k < n; k++) {
            float a = A[i * n + k];
            const float *bk = B + k * n;
            for (size_t j = 0; j < n; j++) ci[j] += a * bk[j];
        }
    }
#endif
}
