#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

static void sort_u32_heap(uint32_t *a, size_t n) {
    if (n < 2) return;
    size_t start = n / 2;
    size_t end = n;
    while (1) {
        size_t root;
        if (start > 0) {
            start--;
            root = start;
        } else {
            end--;
            if (end == 0) return;
            uint32_t t = a[end];
            a[end] = a[0];
            a[0] = t;
            root = 0;
        }
        while (1) {
            size_t child = 2 * root + 1;
            if (child >= end) break;
            if (child + 1 < end && a[child + 1] > a[child]) child++;
            if (a[child] > a[root]) {
                uint32_t t = a[child];
                a[child] = a[root];
                a[root] = t;
                root = child;
            } else break;
        }
    }
}

void sort_u32(uint32_t *a, size_t n) {
    if (n < 2) return;
    if (n <= 64) {
        for (size_t i = 1; i < n; i++) {
            uint32_t x = a[i];
            size_t j = i;
            while (j > 0 && a[j - 1] > x) {
                a[j] = a[j - 1];
                j--;
            }
            a[j] = x;
        }
        return;
    }

    uint32_t *tmp = (uint32_t *)malloc(n * sizeof(uint32_t));
    if (!tmp) {
        sort_u32_heap(a, n);
        return;
    }

    static uint32_t cnt[3][2048];
    memset(cnt, 0, sizeof(cnt));

    for (size_t i = 0; i < n; i++) {
        uint32_t x = a[i];
        cnt[0][x & 2047]++;
        cnt[1][(x >> 11) & 2047]++;
        cnt[2][(x >> 22) & 2047]++;
    }

    uint32_t *src = a;
    uint32_t *dst = tmp;
    static const int shifts[3] = {0, 11, 22};

    for (int p = 0; p < 3; p++) {
        int sh = shifts[p];
        uint32_t *c = cnt[p];
        uint32_t first = (src[0] >> sh) & 2047;
        if (c[first] == n) continue; /* all same digit: skip */

        uint32_t sum = 0;
        for (int b = 0; b < 2048; b++) {
            uint32_t t = c[b];
            c[b] = sum;
            sum += t;
        }
        for (size_t i = 0; i < n; i++) {
            uint32_t x = src[i];
            uint32_t d = (x >> sh) & 2047;
            dst[c[d]++] = x;
        }
        uint32_t *t = src;
        src = dst;
        dst = t;
    }

    if (src != a) {
        memcpy(a, src, n * sizeof(uint32_t));
    }
    free(tmp);
}
```
