#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define KSEG 32768

static unsigned char kseg[KSEG];

uint64_t count_primes(uint64_t n) {
    if (n < 2) return 0;
    if (n < 3) return 1;

    uint64_t M = (n - 1) / 2; /* index i represents 2i+1, i in [0, M] */

    uint64_t r = (uint64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    /* base odd primes up to r */
    uint64_t np = 0;
    uint64_t *pr = NULL;
    if (r >= 3) {
        unsigned char *cs = (unsigned char *)calloc(r + 1, 1);
        pr = (uint64_t *)malloc((r / 2 + 2) * sizeof(uint64_t));
        for (uint64_t i = 3; i <= r; i += 2) {
            if (!cs[i]) {
                pr[np++] = i;
                for (uint64_t j = i * i; j <= r; j += 2 * i) cs[j] = 1;
            }
        }
        free(cs);
    }

    uint64_t *nx = (uint64_t *)malloc((np + 1) * sizeof(uint64_t));
    for (uint64_t j = 0; j < np; j++) {
        uint64_t p = pr[j];
        nx[j] = (p * p - 1) / 2;
    }

    uint64_t cnt = 1; /* prime 2 */
    for (uint64_t s = 0; s <= M; s += KSEG) {
        uint64_t len = M + 1 - s;
        if (len > KSEG) len = KSEG;
        memset(kseg, 0, (size_t)len);
        if (s == 0) kseg[0] = 1; /* number 1 */
        uint64_t high = 2 * (s + len - 1) + 1;
        uint64_t end = s + len;
        for (uint64_t j = 0; j < np; j++) {
            uint64_t p = pr[j];
            if (p * p > high) break;
            uint64_t st = nx[j];
            while (st < end) {
                kseg[st - s] = 1;
                st += p;
            }
            nx[j] = st;
        }
        uint64_t z = 0;
        for (uint64_t k = 0; k < len; k++) z += (kseg[k] == 0);
        cnt += z;
    }

    free(nx);
    free(pr);
    return cnt;
}
