#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static int rs_cmp(const void *x, const void *y) {
    uint32_t a = *(const uint32_t *)x, b = *(const uint32_t *)y;
    return (a > b) - (a < b);
}

static void rs_ins(uint32_t *a, size_t n) {
    for (size_t i = 1; i < n; i++) {
        uint32_t v = a[i];
        size_t j = i;
        while (j > 0 && a[j - 1] > v) {
            a[j] = a[j - 1];
            j--;
        }
        a[j] = v;
    }
}

void sort_u32(uint32_t *a, size_t n) {
    if (n < 2) return;
    if (n <= 32) {
        rs_ins(a, n);
        return;
    }
    uint32_t *tmp = (uint32_t *)malloc(n * sizeof(uint32_t));
    if (!tmp) {
        qsort(a, n, sizeof(uint32_t), rs_cmp);
        return;
    }
    static uint32_t cnt[3][2048];
    memset(cnt, 0, sizeof cnt);
    for (size_t i = 0; i < n; i++) {
        uint32_t v = a[i];
        cnt[0][v & 2047]++;
        cnt[1][(v >> 11) & 2047]++;
        cnt[2][(v >> 22) & 2047]++;
    }
    uint32_t *src = a, *dst = tmp;
    for (int p = 0; p < 3; p++) {
        int shift = 11 * p;
        uint32_t *c = cnt[p];
        uint32_t d0 = (src[0] >> shift) & 2047;
        if (c[d0] == n) continue;
        uint32_t sum = 0;
        for (int b = 0; b < 2048; b++) {
            uint32_t t = c[b];
            c[b] = sum;
            sum += t;
        }
        for (size_t i = 0; i < n; i++) {
            uint32_t v = src[i];
            dst[c[(v >> shift) & 2047]++] = v;
        }
        uint32_t *t = src;
        src = dst;
        dst = t;
    }
    if (src != a) memcpy(a, src, n * sizeof(uint32_t));
    free(tmp);
}
