#include <stdint.h>
#include <stddef.h>
#include <string.h>
#ifdef __AVX2__
#include <immintrin.h>
#endif

uint64_t count_substr(const char *text, size_t n, const char *pat, size_t m) {
    if (m == 0 || m > n) {
        if (m == 0) return (uint64_t)(n + 1);
        return 0;
    }
    size_t P = n - m + 1;
    uint64_t cnt = 0;
    size_t i = 0;
#ifdef __AVX2__
    __m256i pv[64];
    for (size_t j = 0; j < m; j++) pv[j] = _mm256_set1_epi8(pat[j]);
    for (; i + 32 <= P; i += 32) {
        __m256i acc = _mm256_cmpeq_epi8(_mm256_loadu_si256((const __m256i *)(text + i)), pv[0]);
        for (size_t j = 1; j < m; j++) {
            __m256i t = _mm256_loadu_si256((const __m256i *)(text + i + j));
            acc = _mm256_and_si256(acc, _mm256_cmpeq_epi8(t, pv[j]));
        }
        cnt += (uint64_t)__builtin_popcount((unsigned)_mm256_movemask_epi8(acc));
    }
#endif
    for (; i < P; i++) {
        size_t j = 0;
        while (j < m && text[i + j] == pat[j]) j++;
        if (j == m) cnt++;
    }
    return cnt;
}
