        end[b] = s;
    }

    for (int b = 0; b < 256; b++) {
        while (next[b] < end[b]) {
            uint32_t v = a[next[b]];
            unsigned d = (v >> shift) & 255u;
            while (d != (unsigned)b) {
                uint32_t t = a[next[d]];
                a[next[d]++] = v;
                v = t;
                d = (v >> shift) & 255u;
            }
            a[next[b]++] = v;
        }
    }

    if (shift == 0) return;
    for (int b = 0; b < 256; b++) {
        if (cnt[b] > 1) {
            afs_sort(a + start[b], cnt[b], shift - 8);
        }
    }
}

static void radix_lsd(uint32_t *a, uint32_t *tmp, size_t n) {
    static size_t cnt[4][256];
    memset(cnt, 0, sizeof(cnt));
    for (size_t i = 0; i < n; i++) {
        uint32_t v = a[i];
        cnt[0][v & 255]++;
        cnt[1][(v >> 8) & 255]++;
        cnt[2][(v >> 16) & 255]++;
        cnt[3][(v >> 24) & 255]++;
    }

    uint32_t *src = a, *dst = tmp;
    for (int p = 0; p < 4; p++) {
        int shift = p * 8;
        if (cnt[p][(src[0] >> shift) & 255] == n) continue; /* all equal digit */
        size_t off[256];
        size_t s = 0;
        for (int b = 0; b < 256; b++) {
            off[b] = s;
            s += cnt[p][b];
        }
        for (size_t i = 0; i < n; i++) {
            uint32_t v = src[i];
            dst[off[(v >> shift) & 255]++] = v;
        }
        uint32_t *t = src;
        src = dst;
        dst = t;
    }
    if (src != a) memcpy(a, src, n * sizeof(uint32_t));
}

void sort_u32(uint32_t *a, size_t n) {
    if (n < 2) return;
    if (n <= 32) {
        sort_small_u32(a, n);
        return;
    }
    if (n <= 4718592) {
        uint32_t *tmp = (uint32_t *)malloc(n * sizeof(uint32_t));
        if (tmp) {
            radix_lsd(a, tmp, n);
            free(tmp);
            return;
        }
    }
    afs_sort(a, n, 24);
}
