uint64_t count_substr(const char *text, size_t n, const char *pat, size_t m) {
    if (m == 0) return (uint64_t)(n + 1);
    if (m > n) return 0;
    uint64_t cnt = 0;
    size_t last = n - m;   /* max valid start position */
    size_t i = 0;

#ifdef __AVX2__
    __m256i pv[64];
    for (size_t j = 0; j < m; j++) pv[j] = _mm256_set1_epi8(pat[j]);
    while (i + 31 <= last) {
        __m256i mask = _mm256_set1_epi8(-1);
        unsigned mm = 0;
        for (size_t j = 0; j < m; j++) {
            __m256i v = _mm256_loadu_si256((const __m256i *)(text + i + j));
            mask = _mm256_and_si256(mask, _mm256_cmpeq_epi8(v, pv[j]));
            mm = (unsigned)_mm256_movemask_epi8(mask);
            if (!mm) break;
        }
        cnt += (uint64_t)__builtin_popcount(mm);
        i += 32;
    }
#else
    __m128i pv[64];
    for (size_t j = 0; j < m; j++) pv[j] = _mm_set1_epi8(pat[j]);
    while (i + 15 <= last) {
        __m128i mask = _mm_set1_epi8(-1);
        unsigned mm = 0;
        for (size_t j = 0; j < m; j++) {
            __m128i v = _mm_loadu_si128((const __m128i *)(text + i + j));
            mask = _mm_and_si128(mask, _mm_cmpeq_epi8(v, pv[j]));
            mm = (unsigned)_mm_movemask_epi8(mask);
            if (!mm) break;
        }
        cnt += (uint64_t)__builtin_popcount(mm);
        i += 16;
    }
#endif

    for (; i <= last; i++) {
        size_t j = 0;
        while (j < m && text[i + j] == pat[j]) j++;
        if (j == m) cnt++;
    }
    return cnt;
