size_t count_distinct_u32(const uint32_t *a, size_t n)
{
    if (n == 0)
        return 0;

    const size_t WORDS = (size_t)1 << 20; /* 2^26 bits = 2^20 uint64 words = 8 MiB */
    uint64_t *bm = (uint64_t *)calloc(WORDS, sizeof(uint64_t));
    if (!bm)
        return 0;

    size_t cnt = 0;
    size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        uint32_t v0 = a[i], v1 = a[i + 1], v2 = a[i + 2], v3 = a[i + 3];
        uint64_t w0 = bm[v0 >> 6], w1 = bm[v1 >> 6];
        uint64_t w2 = bm[v2 >> 6], w3 = bm[v3 >> 6];
        uint64_t m0 = (uint64_t)1 << (v0 & 63);
        uint64_t m1 = (uint64_t)1 << (v1 & 63);
        uint64_t m2 = (uint64_t)1 << (v2 & 63);
        uint64_t m3 = (uint64_t)1 << (v3 & 63);
        cnt += (w0 & m0) == 0;
        bm[v0 >> 6] = w0 | m0;
        cnt += (w1 & m1) == 0;
        bm[v1 >> 6] = w1 | m1;
        cnt += (w2 & m2) == 0;
        bm[v2 >> 6] = w2 | m2;
        cnt += (w3 & m3) == 0;
        bm[v3 >> 6] = w3 | m3;
    }
    for (; i < n; i++) {
        uint32_t v = a[i];
        uint64_t w = bm[v >> 6];
        uint64_t m = (uint64_t)1 << (v & 63);
        cnt += (w & m) == 0;
        bm[v >> 6] = w | m;
    }

    free(bm);
    return cnt;
}
