```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>

size_t levenshtein(const char *s, size_t n, const char *t, size_t m)
{
    if (n == 0) return m;
    if (m == 0) return n;

    unsigned char idx[256];
    memset(idx, 0xff, sizeof(idx));
    size_t k = 0;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)s[i];
        if (idx[c] == 0xff) idx[c] = (unsigned char)k++;
    }

    size_t B = (n + 63) / 64;
    /* k+1 rows: last row is all zeros (for chars absent from s) */
    uint64_t *peq = (uint64_t *)calloc((k + 1) * B, sizeof(uint64_t));
    uint64_t *Pv = (uint64_t *)malloc(B * sizeof(uint64_t));
    uint64_t *Mv = (uint64_t *)malloc(B * sizeof(uint64_t));
    if (!peq || !Pv || !Mv) {
        free(peq); free(Pv); free(Mv);
        return 0;
    }

    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)s[i];
        peq[(size_t)idx[c] * B + (i >> 6)] |= 1ULL << (i & 63);
    }

    for (size_t b = 0; b < B; b++) {
        Pv[b] = ~0ULL;
        Mv[b] = 0;
    }

    unsigned r = (unsigned)((n - 1) & 63);
    uint64_t rbit = 1ULL << r;
    size_t score = n;

    for (size_t j = 0; j < m; j++) {
        unsigned char c = (unsigned char)t[j];
        size_t id = idx[c];
        const uint64_t *eqrow = peq + (id == 0xff ? k : id) * B;
        int hin = 1;
        for (size_t b = 0; b + 1 < B; b++) {
            uint64_t Eq = eqrow[b];
            uint64_t pv = Pv[b];
            uint64_t mv = Mv[b];
            uint64_t Xv = Eq | mv;
            if (hin < 0) Eq |= 1ULL;
            uint64_t Xh = (((Eq & pv) + pv) ^ pv) | Eq;
            uint64_t Ph = mv | ~(Xh | pv);
            uint64_t Mh = pv & Xh;
            int hout;
            if (Ph >> 63) hout = 1;
            else if (Mh >> 63) hout = -1;
            else hout = 0;
            Ph <<= 1;
            Mh <<= 1;
            if (hin < 0) Mh |= 1ULL;
            else if (hin > 0) Ph |= 1ULL;
            Pv[b] = Mh | ~(Xv | Ph);
            Mv[b] = Ph & Xv;
            hin = hout;
        }
        {
            size_t b = B - 1;
            uint64_t Eq = eqrow[b];
            uint64_t pv = Pv[b];
            uint64_t mv = Mv[b];
            uint64_t Xv = Eq | mv;
            if (hin < 0) Eq |= 1ULL;
            uint64_t Xh = (((Eq & pv) + pv) ^ pv) | Eq;
            uint64_t Ph = mv | ~(Xh | pv);
            uint64_t Mh = pv & Xh;
            int hout;
            if (Ph & rbit) hout = 1;
            else if (Mh & rbit) hout = -1;
            else hout = 0;
            Ph <<= 1;
            Mh <<= 1;
            if (hin < 0) Mh |= 1ULL;
            else if (hin > 0) Ph |= 1ULL;
            Pv[b] = Mh | ~(Xv | Ph);
            Mv[b] = Ph & Xv;
            hin = hout;
        }
        score += (size_t)(long)hin;
        /* adjust for negative hin */
        (void)0;
    }

    free(peq);
    free(Pv);
    free(Mv);
    return score;
}
