#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static inline int lev_blk(uint64_t Eq, uint64_t *pvp, uint64_t *mvp, int hin, unsigned r)
{
    uint64_t Pv = *pvp, Mv = *mvp;
    uint64_t hn = (uint64_t)(hin < 0);
    uint64_t Xv = Eq | Mv;
    Eq |= hn;
    uint64_t Xh = (((Eq & Pv) + Pv) ^ Pv) | Eq;
    uint64_t Ph = Mv | ~(Xh | Pv);
    uint64_t Mh = Pv & Xh;
    int hout = (int)((Ph >> r) & 1u) - (int)((Mh >> r) & 1u);
    Ph = (Ph << 1) | (uint64_t)(hin > 0);
    Mh = (Mh << 1) | hn;
    *pvp = Mh | ~(Xv | Ph);
    *mvp = Ph & Xv;
    return hout;
}

size_t levenshtein(const char *s, size_t n, const char *t, size_t m)
{
    const unsigned char *P, *T;
    size_t p, q;
    if (n <= m) {
        P = (const unsigned char *)s; p = n;
        T = (const unsigned char *)t; q = m;
    } else {
        P = (const unsigned char *)t; p = m;
        T = (const unsigned char *)s; q = n;
    }
    if (p == 0) return q;
    if (q == 0) return p;

    size_t nb = (p + 63) / 64;
    uint64_t *Peq = (uint64_t *)calloc(256 * nb, sizeof(uint64_t));
    uint64_t *Pv = (uint64_t *)malloc(nb * sizeof(uint64_t));
    uint64_t *Mv = (uint64_t *)calloc(nb, sizeof(uint64_t));
    if (!Peq || !Pv || !Mv) {
        free(Peq); free(Pv); free(Mv);
        return 0;
    }
    for (size_t i = 0; i < p; i++) {
        Peq[(size_t)P[i] * nb + (i >> 6)] |= (uint64_t)1 << (i & 63);
    }
    for (size_t b = 0; b < nb; b++) Pv[b] = ~(uint64_t)0;

    unsigned r = (unsigned)((p - 1) & 63);
    size_t last = nb - 1;
    long long score = (long long)p;

    for (size_t j = 0; j < q; j++) {
        const uint64_t *eq = Peq + (size_t)T[j] * nb;
        int hin = 1;
        for (size_t b = 0; b < last; b++) {
            hin = lev_blk(eq[b], &Pv[b], &Mv[b], hin, 63u);
        }
        int hout = lev_blk(eq[last], &Pv[last], &Mv[last], hin, r);
        score += hout;
    }

    free(Peq);
    free(Pv);
    free(Mv);
    return (size_t)score;
