#include <stdint.h>
#include <stddef.h>
#include <immintrin.h>

static uint32_t k_crc_bitwise(uint32_t crc, const uint8_t *p, size_t n) {
    uint32_t c = ~crc;
    for (size_t i = 0; i < n; i++) {
        c ^= p[i];
        for (int j = 0; j < 8; j++) {
            c = (c >> 1) ^ (0xEDB88320u & (uint32_t)(-(int32_t)(c & 1u)));
        }
    }
    return ~c;
}

static inline __m128i k_reduce128(__m128i a, __m128i b, __m128i keys) {
    __m128i t1 = _mm_clmulepi64_si128(a, keys, 0x00);
    __m128i t2 = _mm_clmulepi64_si128(a, keys, 0x11);
    return _mm_xor_si128(_mm_xor_si128(b, t1), t2);
}

uint32_t crc32_ieee(const uint8_t *data, size_t n) {
    const long long K1 = 0x154442bd4LL;
    const long long K2 = 0x1c6e41596LL;
    const long long K3 = 0x1751997d0LL;
    const long long K4 = 0xccaa009eLL;
    const long long K5 = 0x163cd6124LL;
    const long long POLY = 0x1DB710641LL;
    const long long UPRIME = 0x1F7011641LL;

    if (n < 128) {
        return k_crc_bitwise(0, data, n);
    }

    const uint8_t *p = data;
    size_t len = n;
    uint32_t crc = 0;

    __m128i x3 = _mm_loadu_si128((const __m128i *)(p + 0));
    __m128i x2 = _mm_loadu_si128((const __m128i *)(p + 16));
    __m128i x1 = _mm_loadu_si128((const __m128i *)(p + 32));
    __m128i x0 = _mm_loadu_si128((const __m128i *)(p + 48));
    p += 64;
    len -= 64;

    x3 = _mm_xor_si128(x3, _mm_cvtsi32_si128((int)(~crc)));

    const __m128i k1k2 = _mm_set_epi64x(K2, K1);
    while (len >= 64) {
        x3 = k_reduce128(x3, _mm_loadu_si128((const __m128i *)(p + 0)), k1k2);
        x2 = k_reduce128(x2, _mm_loadu_si128((const __m128i *)(p + 16)), k1k2);
        x1 = k_reduce128(x1, _mm_loadu_si128((const __m128i *)(p + 32)), k1k2);
        x0 = k_reduce128(x0, _mm_loadu_si128((const __m128i *)(p + 48)), k1k2);
        p += 64;
        len -= 64;
    }

    const __m128i k3k4 = _mm_set_epi64x(K4, K3);
    __m128i x = k_reduce128(x3, x2, k3k4);
    x = k_reduce128(x, x1, k3k4);
    x = k_reduce128(x, x0, k3k4);

    /* 128 -> 64 bits */
    __m128i t = _mm_clmulepi64_si128(x, k3k4, 0x10);
    const __m128i mask = _mm_setr_epi32(-1, 0, -1, 0);
    x = _mm_srli_si128(x, 8);
    x = _mm_xor_si128(x, t);

    const __m128i k5k0 = _mm_set_epi64x(0, K5);
    __m128i x2b = _mm_srli_si128(x, 4);
    x = _mm_and_si128(x, mask);
    x = _mm_clmulepi64_si128(x, k5k0, 0x00);
    x = _mm_xor_si128(x, x2b);

    /* Barrett reduction 64 -> 32 */
    const __m128i pu = _mm_set_epi64x(UPRIME, POLY);
    __m128i t1 = _mm_clmulepi64_si128(x, pu, 0x10);
    __m128i t2 = _mm_clmulepi64_si128(t1, pu, 0x00);
    x = _mm_xor_si128(x, t2);
    crc = ~((uint32_t)_mm_extract_epi32(x, 1));

    if (len > 0) {
        crc = k_crc_bitwise(crc, p, len);
    }
    return crc;
}
