```c
#include <stdint.h>
#include <immintrin.h>

static inline void mstep(__m256d *zx, __m256d *zy, __m256d *alive,
                         __m256d cx, __m256d cy, __m256d four, __m256d two)
{
    __m256d zx2 = _mm256_mul_pd(*zx, *zx);
    __m256d zy2 = _mm256_mul_pd(*zy, *zy);
    __m256d mag = _mm256_add_pd(zx2, zy2);
    *alive = _mm256_and_pd(*alive, _mm256_cmp_pd(mag, four, _CMP_LE_OQ));
    __m256d nzy = _mm256_add_pd(_mm256_mul_pd(_mm256_mul_pd(*zx, *zy), two), cy);
    __m256d nzx = _mm256_add_pd(_mm256_sub_pd(zx2, zy2), cx);
    *zx = nzx;
    *zy = nzy;
}

static inline double mcxof(int p, int w)
{
    return -2.0 + 3.0 * (p + 0.5) / w;
}

uint64_t mandel_count(int w, int h, int max_iter)
{
    uint64_t total = 0;
    if (w <= 0 || h <= 0)
        return 0;
    const __m256d four = _mm256_set1_pd(4.0);
    const __m256d two = _mm256_set1_pd(2.0);

    for (int py = 0; py < h; py++) {
        double cy_s = -1.5 + 3.0 * (py + 0.5) / h;
        __m256d cy = _mm256_set1_pd(cy_s);
        for (int px0 = 0; px0 < w; px0 += 8) {
            double cxa[4], cxb[4];
            long long ma[4], mb[4];
            for (int k = 0; k < 4; k++) {
                int pa = px0 + k;
                int pb = px0 + 4 + k;
                cxa[k] = (pa < w) ? mcxof(pa, w) : 0.0;
                ma[k] = (pa < w) ? -1LL : 0LL;
                cxb[k] = (pb < w) ? mcxof(pb, w) : 0.0;
                mb[k] = (pb < w) ? -1LL : 0LL;
            }
            __m256d cxA = _mm256_loadu_pd(cxa);
            __m256d cxB = _mm256_loadu_pd(cxb);
            __m256d aliveA = _mm256_castsi256_pd(_mm256_loadu_si256((const __m256i *)ma));
            __m256d aliveB = _mm256_castsi256_pd(_mm256_loadu_si256((const __m256i *)mb));
            __m256d zxA = _mm256_setzero_pd(), zyA = _mm256_setzero_pd();
            __m256d zxB = _mm256_setzero_pd(), zyB = _mm256_setzero_pd();

            int n = 0;
            int done = 0;
            while (n + 4 <= max_iter) {
                mstep(&zxA, &zyA, &aliveA, cxA, cy, four, two);
                mstep(&zxB, &zyB, &aliveB, cxB, cy, four, two);
                mstep(&zxA, &zyA, &aliveA, cxA, cy, four, two);
                mstep(&zxB, &zyB, &aliveB, cxB, cy, four, two);
                mstep(&zxA, &zyA, &aliveA, cxA, cy, four, two);
                mstep(&zxB, &zyB, &aliveB, cxB, cy, four, two);
                mstep(&zxA, &zyA, &aliveA, cxA, cy, four, two);
                mstep(&zxB, &zyB, &aliveB, cxB, cy, four, two);
                n += 4;
                if ((_mm256_movemask_pd(aliveA) | _mm256_movemask_pd(aliveB)) == 0) {
                    done = 1;
                    break;
                }
            }
            if (!done) {
                while (n < max_iter) {
                    mstep(&zxA, &zyA, &aliveA, cxA, cy, four, two);
                    mstep(&zxB, &zyB, &aliveB, cxB, cy, four, two);
                    n++;
                }
            }
            total += (uint64_t)__builtin_popcount(_mm256_movemask_pd(aliveA));
            total += (uint64_t)__builtin_popcount(_mm256_movemask_pd(aliveB));
        }
    }
    return total;
}
