This uses Myers/Hyyrö bit-parallel edit distance, processing 64 pattern rows per word. That's about 564k block steps for n = m = 6000, versus 36M cell updates for the straightforward DP. Peak extra memory is about 200 KB (the per-character match masks), well under the 4 MiB limit. I haven't compiled or run it.

<answer>
```c
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

size_t levenshtein(const char *s, size_t n, const char *t, size_t m) {
    if (n == 0) return m;
    if (m == 0) return n;

    size_t W = (n + 63) >> 6;
    uint64_t *peq = (uint64_t *)calloc(256 * W, sizeof(uint64_t));
    uint64_t *P = (uint64_t *)malloc(W * sizeof(uint64_t));
    uint64_t *M = (uint64_t *)malloc(W * sizeof(uint64_t));
    if (!peq || !P || !M) {
        free(peq); free(P); free(M);
        /* fallback: plain two-row DP */
        size_t *prev = (size_t *)malloc((m + 1) * sizeof(size_t));
        size_t *cur = (size_t *)malloc((m + 1) * sizeof(size_t));
        if (!prev || !cur) { free(prev); free(cur); return 0; }
        for (size_t j = 0; j <= m; j++) prev[j] = j;
        for (size_t i = 1; i <= n; i++) {
            cur[0] = i;
            for (size_t j = 1; j <= m; j++) {
                size_t a = prev[j - 1] + (s[i - 1] != t[j - 1]);
                size_t b = prev[j] + 1;
                size_t c = cur[j - 1] + 1;
                size_t r = a < b ? a : b;
                cur[j] = r < c ? r : c;
            }
            size_t *tmp = prev; prev = cur; cur = tmp;
        }
        size_t res = prev[m];
        free(prev); free(cur);
        return res;
    }

    for (size_t i = 0; i < n; i++) {
        peq[(size_t)(unsigned char)s[i] * W + (i >> 6)] |= 1ULL << (i & 63);
    }
    for (size_t b = 0; b < W; b++) {
        P[b] = ~0ULL;
        M[b] = 0;
    }

    size_t score = n;
    size_t last = W - 1;
    uint64_t lastbit = 1ULL << ((n - 1) & 63);

    for (size_t j = 0; j < m; j++) {
        const uint64_t *eqrow = peq + (size_t)(unsigned char)t[j] * W;
        int hin = 1;
        for (size_t b = 0; b < W; b++) {
            uint64_t Eq = eqrow[b];
            uint64_t pv = P[b];
            uint64_t mv = M[b];
            uint64_t Xv = Eq | mv;
            if (hin < 0) Eq |= 1ULL;
            uint64_t Xh = (((Eq & pv) + pv) ^ pv) | Eq;
            uint64_t Ph = mv | ~(Xh | pv);
            uint64_t Mh = pv & Xh;
            if (b == last) {
                if (Ph & lastbit) score++;
                else if (Mh & lastbit) score--;
                break;
            }
            int hout = (int)(Ph >> 63) - (int)(Mh >> 63);
            Ph <<= 1;
            Mh <<= 1;
            if (hin > 0) Ph |= 1ULL;
            else if (hin < 0) Mh |= 1ULL;
            P[b] = Mh | ~(Xv | Ph);
            M[b] = Ph & Xv;
            hin = hout;
        }
        /* last block handled separately with its own hin */
        {
            uint64_t Eq = eqrow[last];
            uint64_t pv = P[last];
            uint64_t mv = M[last];
            uint64_t Xv = Eq | mv;
            if (hin < 0) Eq |= 1ULL;
            uint64_t Xh = (((Eq & pv) + pv) ^ pv) | Eq;
            uint64_t Ph = mv | ~(Xh | pv);
            uint64_t Mh = pv & Xh;
            if (Ph & lastbit) score++;
            else if (Mh & lastbit) score--;
            Ph <<= 1;
            Mh <<= 1;
            if (hin > 0) Ph |= 1ULL;
            else if (hin < 0) Mh |= 1ULL;
            P[last] = Mh | ~(Xv | Ph);
            M[last] = Ph & Xv;
        }
    }

    free(peq);
    free(P);
    free(M);
    return score;
}
