#include <immintrin.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>

static void k_build_tab(uint32_t t[256]) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int k = 0; k < 8; k++)
            c = (c & 1) ? (c >> 1) ^ 0xEDB88320u : (c >> 1);
        t[i] = c;
    }
}

__attribute__((target("pclmul,sse4.1")))
static uint32_t k_fold_body(const uint8_t *data, size_t n, uint32_t crc, size_t *consumed) {
    const uint8_t *p = data;
    const __m128i k1k2 = _mm_set_epi64x(0x01c6e41596LL, 0x0154442bd4LL);
    const __m128i k3k4 = _mm_set_epi64x(0x00ccaa009eLL, 0x01751997d0LL);
    const __m128i k5k0 = _mm_set_epi64x(0LL, 0x0163cd6124LL);
    const __m128i poly = _mm_set_epi64x(0x01f7011641LL, 0x01db710641LL);

    __m128i x1 = _mm_loadu_si128((const __m128i *)(p));
    __m128i x2 = _mm_loadu_si128((const __m128i *)(p + 16));
    __m128i x3 = _mm_loadu_si128((const __m128i *)(p + 32));
    __m128i x4 = _mm_loadu_si128((const __m128i *)(p + 48));
    x1 = _mm_xor_si128(x1, _mm_cvtsi32_si128((int)crc));
    p += 64;
    n -= 64;

    while (n >= 64) {
        __m128i x5 = _mm_clmulepi64_si128(x1, k1k2, 0x00);
        __m128i x6 = _mm_clmulepi64_si128(x2, k1k2, 0x00);
        __m128i x7 = _mm_clmulepi64_si128(x3, k1k2, 0x00);
        __m128i x8 = _mm_clmulepi64_si128(x4, k1k2, 0x00);
        x1 = _mm_clmulepi64_si128(x1, k1k2, 0x11);
        x2 = _mm_clmulepi64_si128(x2, k1k2, 0x11);
        x3 = _mm_clmulepi64_si128(x3, k1k2, 0x11);
        x4 = _mm_clmulepi64_si128(x4, k1k2, 0x11);
        __m128i y5 = _mm_loadu_si128((const __m128i *)(p));
        __m128i y6 = _mm_loadu_si128((const __m128i *)(p + 16));
        __m128i y7 = _mm_loadu_si128((const __m128i *)(p + 32));
        __m128i y8 = _mm_loadu_si128((const __m128i *)(p + 48));
        x1 = _mm_xor_si128(_mm_xor_si128(x1, x5), y5);
        x2 = _mm_xor_si128(_mm_xor_si128(x2, x6), y6);
        x3 = _mm_xor_si128(_mm_xor_si128(x3, x7), y7);
        x4 = _mm_xor_si128(_mm_xor_si128(x4, x8), y8);
        p += 64;
        n -= 64;
    }

    /* fold 4 accumulators into one */
    {
        __m128i t;
        t = _mm_clmulepi64_si128(x1, k3k4, 0x00);
        x1 = _mm_clmulepi64_si128(x1, k3k4, 0x11);
        x1 = _mm_xor_si128(_mm_xor_si128(x1, x2), t);
        t = _mm_clmulepi64_si128(x1, k3k4, 0x00);
        x1 = _mm_clmulepi64_si128(x1, k3k4, 0x11);
        x1 = _mm_xor_si128(_mm_xor_si128(x1, x3), t);
        t = _mm_clmulepi64_si128(x1, k3k4, 0x00);
        x1 = _mm_clmulepi64_si128(x1, k3k4, 0x11);
        x1 = _mm_xor_si128(_mm_xor_si128(x1, x4), t);
    }

    while (n >= 16) {
        __m128i x2b = _mm_loadu_si128((const __m128i *)p);
        __m128i t = _mm_clmulepi64_si128(x1, k3k4, 0x00);
        x1 = _mm_clmulepi64_si128(x1, k3k4, 0x11);
        x1 = _mm_xor_si128(_mm_xor_si128(x1, x2b), t);
        p += 16;
        n -= 16;
    }

    /* 128 -> 64 -> 32 reduction */
    {
        const __m128i mask = _mm_setr_epi32(-1, 0, -1, 0);
        __m128i x2r = _mm_clmulepi64_si128(x1, k3k4, 0x10);
        x1 = _mm_srli_si128(x1, 8);
        x1 = _mm_xor_si128(x1, x2r);
        x2r = _mm_srli_si128(x1, 4);
        x1 = _mm_and_si128(x1, mask);
        x1 = _mm_clmulepi64_si128(x1, k5k0, 0x00);
        x1 = _mm_xor_si128(x1, x2r);
        /* Barrett */
        x2r = _mm_and_si128(x1, mask);
        x2r = _mm_clmulepi64_si128(x2r, poly, 0x10);
        x2r = _mm_and_si128(x2r, mask);
        x2r = _mm_clmulepi64_si128(x2r, poly, 0x00);
        x1 = _mm_xor_si128(x1, x2r);
        crc = (uint32_t)_mm_extract_epi32(x1, 1);
    }

    *consumed = (size_t)(p - data);
    return crc;
}

uint32_t crc32_ieee(const uint8_t *data, size_t n) {
    uint32_t t[256];
    k_build_tab(t);
    uint32_t c = 0xFFFFFFFFu;
    size_t i = 0;
    if (n >= 64) {
        c = k_fold_body(data, n, c, &i);
    }
    for (; i < n; i++)
        c = t[(c ^ data[i]) & 0xFFu] ^ (c >> 8);
    return ~c;
}
