#include <immintrin.h>

uint64_t mandel_count(int w, int h, int max_iter)
{
    if (w <= 0 || h <= 0)
        return 0;
    uint64_t total = 0;

#ifdef __AVX2__
    const __m256d four  = _mm256_set1_pd(4.0);
    const __m256d two   = _mm256_set1_pd(2.0);
    const __m256d three = _mm256_set1_pd(3.0);
    const __m256d m2    = _mm256_set1_pd(-2.0);
    const __m256d lanef = _mm256_setr_pd(0.5, 1.5, 2.5, 3.5);
    const __m256d lanei = _mm256_setr_pd(0.0, 1.0, 2.0, 3.0);
    const __m256d W = _mm256_set1_pd((double)w);
    for (int py = 0; py < h; py++) {
        double yc = -1.5 + 3.0 * (py + 0.5) / h;
        __m256d cy = _mm256_set1_pd(yc);
        for (int px = 0; px < w; px += 4) {
            __m256d pxv = _mm256_set1_pd((double)px);
            __m256d cx = _mm256_add_pd(m2,
                _mm256_div_pd(_mm256_mul_pd(three, _mm256_add_pd(pxv, lanef)), W));
            __m256d alive = _mm256_cmp_pd(_mm256_add_pd(pxv, lanei), W, _CMP_LT_OQ);
            __m256d zr = _mm256_setzero_pd();
            __m256d zi = _mm256_setzero_pd();
            for (int it = 0; it < max_iter; it++) {
                __m256d zr2 = _mm256_mul_pd(zr, zr);
                __m256d zi2 = _mm256_mul_pd(zi, zi);
                __m256d nzi = _mm256_add_pd(_mm256_mul_pd(_mm256_mul_pd(two, zr), zi), cy);
                zr = _mm256_add_pd(_mm256_sub_pd(zr2, zi2), cx);
                zi = nzi;
                __m256d mag = _mm256_add_pd(_mm256_mul_pd(zr, zr), _mm256_mul_pd(zi, zi));
                __m256d mk = _mm256_cmp_pd(mag, four, _CMP_LE_OQ);
                alive = _mm256_and_pd(alive, mk);
                if ((it & 7) == 7 && _mm256_movemask_pd(alive) == 0)
                    break;
            }
            total += (uint64_t)__builtin_popcount(_mm256_movemask_pd(alive));
        }
    }
#else
    for (int py = 0; py < h; py++) {
        double yc = -1.5 + 3.0 * (py + 0.5) / h;
        for (int px = 0; px < w; px++) {
            double xc = -2.0 + 3.0 * (px + 0.5) / w;
            double zr = 0.0, zi = 0.0;
            int ok = 1;
            for (int it = 0; it < max_iter; it++) {
                double nzr = zr * zr - zi * zi + xc;
                double nzi = 2.0 * zr * zi + yc;
                zr = nzr;
                zi = nzi;
                if (!(zr * zr + zi * zi <= 4.0)) { ok = 0; break; }
            }
            total += (uint64_t)ok;
        }
    }
#endif
    return total;
}
