            __m256d vA = _mm256_cmp_pd(pxa, wv, _CMP_LT_OQ);
            __m256d vB = _mm256_cmp_pd(pxb, wv, _CMP_LT_OQ);

            /* main cardioid */
            __m256d xmA = _mm256_sub_pd(cra, quarter);
            __m256d xmB = _mm256_sub_pd(crb, quarter);
            __m256d qA = _mm256_add_pd(_mm256_mul_pd(xmA, xmA), ci2);
            __m256d qB = _mm256_add_pd(_mm256_mul_pd(xmB, xmB), ci2);
            __m256d c1A = _mm256_cmp_pd(_mm256_mul_pd(qA, _mm256_add_pd(qA, xmA)),
                                        _mm256_mul_pd(quarter, ci2), _CMP_LE_OQ);
            __m256d c1B = _mm256_cmp_pd(_mm256_mul_pd(qB, _mm256_add_pd(qB, xmB)),
                                        _mm256_mul_pd(quarter, ci2), _CMP_LE_OQ);
            /* period-2 bulb */
            __m256d xpA = _mm256_add_pd(cra, one);
            __m256d xpB = _mm256_add_pd(crb, one);
            __m256d c2A = _mm256_cmp_pd(_mm256_add_pd(_mm256_mul_pd(xpA, xpA), ci2),
                                        sixteenth, _CMP_LE_OQ);
            __m256d c2B = _mm256_cmp_pd(_mm256_add_pd(_mm256_mul_pd(xpB, xpB), ci2),
                                        sixteenth, _CMP_LE_OQ);
            __m256d inA = _mm256_or_pd(c1A, c2A);
            __m256d inB = _mm256_or_pd(c1B, c2B);

            __m256d insA = _mm256_and_pd(inA, vA);
            __m256d insB = _mm256_and_pd(inB, vB);
            __m256d alA = _mm256_andnot_pd(inA, vA);
            __m256d alB = _mm256_andnot_pd(inB, vB);

            __m256d zrA = zero, ziA = zero, zrB = zero, ziB = zero;

            for (int it = 0; it < max_iter; it++) {
                __m256d any = _mm256_or_pd(alA, alB);
                if (_mm256_movemask_pd(any) == 0) break;

                __m256d zr2A = _mm256_mul_pd(zrA, zrA);
                __m256d zi2A = _mm256_mul_pd(ziA, ziA);
                __m256d zr2B = _mm256_mul_pd(zrB, zrB);
                __m256d zi2B = _mm256_mul_pd(ziB, ziB);

                __m256d nziA = _mm256_add_pd(_mm256_mul_pd(_mm256_mul_pd(two, zrA), ziA), ci);
                __m256d nziB = _mm256_add_pd(_mm256_mul_pd(_mm256_mul_pd(two, zrB), ziB), ci);
                __m256d nzrA = _mm256_add_pd(_mm256_sub_pd(zr2A, zi2A), cra);
                __m256d nzrB = _mm256_add_pd(_mm256_sub_pd(zr2B, zi2B), crb);

                __m256d magA = _mm256_add_pd(_mm256_mul_pd(nzrA, nzrA), _mm256_mul_pd(nziA, nziA));
                __m256d magB = _mm256_add_pd(_mm256_mul_pd(nzrB, nzrB), _mm256_mul_pd(nziB, nziB));

                alA = _mm256_and_pd(alA, _mm256_cmp_pd(magA, four, _CMP_LE_OQ));
                alB = _mm256_and_pd(alB, _mm256_cmp_pd(magB, four, _CMP_LE_OQ));

                zrA = nzrA; ziA = nziA;
                zrB = nzrB; ziB = nziB;
            }

            total += (uint64_t)__builtin_popcount(_mm256_movemask_pd(alA))
                   + (uint64_t)__builtin_popcount(_mm256_movemask_pd(alB))
                   + (uint64_t)__builtin_popcount(_mm256_movemask_pd(insA))
                   + (uint64_t)__builtin_popcount(_mm256_movemask_pd(insB));
        }
    }
    return total;
}
