This uses PCLMULQDQ folding over 64-byte blocks with four accumulators, then a table-driven CRC over the final 16 bytes. I have not compiled or run it, and the fold constants are recalled from the standard IEEE CRC-32 folding constants rather than derived or tested here.

<answer>
```c
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#if defined(__x86_64__) && defined(__PCLMUL__) && defined(__SSE4_1__)
#include <immintrin.h>
#define K_HAVE_PCLMUL 1
#endif

static void k_make_table(uint32_t t[256]) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int k = 0; k < 8; k++)
            c = (c & 1) ? (c >> 1) ^ 0xEDB88320u : (c >> 1);
        t[i] = c;
    }
}

static inline uint32_t k_tbl_update(const uint32_t *t, uint32_t crc,
                                    const uint8_t *p, size_t n) {
    for (size_t i = 0; i < n; i++)
        crc = t[(crc ^ p[i]) & 0xFF] ^ (crc >> 8);
    return crc;
}

#ifdef K_HAVE_PCLMUL
static inline __m128i k_fold(__m128i x, __m128i k) {
    return _mm_xor_si128(_mm_clmulepi64_si128(x, k, 0x00),
                         _mm_clmulepi64_si128(x, k, 0x11));
}
#endif

uint32_t crc32_ieee(const uint8_t *data, size_t n) {
    uint32_t t[256];
    k_make_table(t);
    uint32_t crc = 0xFFFFFFFFu;
    const uint8_t *d = data;

#ifdef K_HAVE_PCLMUL
    if (n >= 64) {
        __m128i x1 = _mm_loadu_si128((const __m128i *)(d + 0));
        __m128i x2 = _mm_loadu_si128((const __m128i *)(d + 16));
        __m128i x3 = _mm_loadu_si128((const __m128i *)(d + 32));
        __m128i x4 = _mm_loadu_si128((const __m128i *)(d + 48));
        x1 = _mm_xor_si128(x1, _mm_cvtsi32_si128((int)crc));
        d += 64;
        n -= 64;

        const __m128i k12 = _mm_set_epi64x((long long)0x1c6e41596LL,
                                           (long long)0x154442bd4LL);
        while (n >= 64) {
            x1 = _mm_xor_si128(k_fold(x1, k12),
                               _mm_loadu_si128((const __m128i *)(d + 0)));
            x2 = _mm_xor_si128(k_fold(x2, k12),
                               _mm_loadu_si128((const __m128i *)(d + 16)));
            x3 = _mm_xor_si128(k_fold(x3, k12),
                               _mm_loadu_si128((const __m128i *)(d + 32)));
            x4 = _mm_xor_si128(k_fold(x4, k12),
                               _mm_loadu_si128((const __m128i *)(d + 48)));
            d += 64;
            n -= 64;
        }

        const __m128i k34 = _mm_set_epi64x((long long)0x0ccaa009eLL,
                                           (long long)0x1751997d0LL);
        __m128i x = _mm_xor_si128(k_fold(x1, k34), x2);
        x = _mm_xor_si128(k_fold(x, k34), x3);
        x = _mm_xor_si128(k_fold(x, k34), x4);
        while (n >= 16) {
            x = _mm_xor_si128(k_fold(x, k34),
                              _mm_loadu_si128((const __m128i *)d));
            d += 16;
            n -= 16;
        }

        uint8_t buf[16];
        _mm_storeu_si128((__m128i *)buf, x);
        crc = k_tbl_update(t, 0, buf, 16);
    }
#endif

    crc = k_tbl_update(t, crc, d, n);
    return ~crc;
}
